// relaysDataSource is the generated plural data source for Relay (List under a parent).
type relaysDataSource struct {
	crud *tf.Crud[*v1alpha1.Relay, *RelayModel]
}

// NewRelaysDataSource returns the generated guard_relays data source.
func NewRelaysDataSource() datasource.DataSource {
	return &relaysDataSource{}
}
func (d *relaysDataSource) Metadata(_ context.Context, req datasource.MetadataRequest, resp *datasource.MetadataResponse) {
	resp.TypeName = req.ProviderTypeName + "_guard_relays"
}
func (d *relaysDataSource) Schema(_ context.Context, _ datasource.SchemaRequest, resp *datasource.SchemaResponse) {
	resp.Schema = RelayListDataSourceSchema()
}
func (d *relaysDataSource) Configure(_ context.Context, req datasource.ConfigureRequest, resp *datasource.ConfigureResponse) {
	crud, diags := newRelayCrud(req.ProviderData)
	resp.Diagnostics.Append(diags...)
	d.crud = crud
}
func (d *relaysDataSource) Read(ctx context.Context, req datasource.ReadRequest, resp *datasource.ReadResponse) {
	if d.crud == nil {
		resp.Diagnostics.AddError("guard_relays data source not configured", "Configure was not called with tf.ProviderData")
		return
	}
	var m RelaysModel
	resp.Diagnostics.Append(req.Config.Get(ctx, &m)...)
	if resp.Diagnostics.HasError() {
		return
	}
	entities, err := d.crud.ListAll(ctx, map[string]string{
		"network_id": m.NetworkId.ValueString(),
		"tenant_id":  m.TenantId.ValueString(),
	})
	if err != nil {
		resp.Diagnostics.AddError("list guard_relays failed", err.Error())
		return
	}
	elems := make([]attr.Value, 0, len(entities))
	for _, e := range entities {
		obj, diags := relayItemFromProto(ctx, d.crud, e)
		resp.Diagnostics.Append(diags...)
		elems = append(elems, obj)
	}
	if resp.Diagnostics.HasError() {
		return
	}
	list, diags := types.ListValue(types.ObjectType{AttrTypes: RelayItemAttrTypes()}, elems)
	resp.Diagnostics.Append(diags...)
	m.Items = list
	resp.Diagnostics.Append(resp.State.Set(ctx, &m)...)
}
